  /**
   * @param {FormData} formData
   * @param {Record<string, unknown>} options
   */
  _appendImportExecutionOptions(formData, options = {}) {
    if (options.seed_paper_id != null) {
      formData.append('seed_paper_id', String(options.seed_paper_id));
    }
    if (options.seed_paper_content != null && options.seed_paper_content.trim() !== '') {
      formData.append('seed_paper_content', options.seed_paper_content.trim());
    }
    if (options.seed_paper_alias != null && options.seed_paper_alias.trim() !== '') {
      formData.append('seed_paper_alias', options.seed_paper_alias.trim());
    }
    if (options.ground_truth_content != null && String(options.ground_truth_content).trim() !== '') {
      formData.append('ground_truth_content', String(options.ground_truth_content).trim());
    }
    if (options.ground_truth_content_type != null && String(options.ground_truth_content_type).trim() !== '') {
      formData.append('ground_truth_content_type', String(options.ground_truth_content_type).trim());
    }
    if (options.prompt_id != null) {
      formData.append('prompt_id', String(options.prompt_id));
    }
    if (options.prompt_content != null && options.prompt_content.trim() !== '') {
      formData.append('prompt_content', options.prompt_content.trim());
    }
    if (options.execution_comment != null && String(options.execution_comment).trim() !== '') {
      formData.append('execution_comment', String(options.execution_comment).trim());
    }
    if (options.existence_check_mode != null && String(options.existence_check_mode).trim() !== '') {
      formData.append('existence_check_mode', String(options.existence_check_mode).trim());
    }
    if (options.authoritative_verification_mode != null && String(options.authoritative_verification_mode).trim() !== '') {
      formData.append('authoritative_verification_mode', String(options.authoritative_verification_mode).trim());
    }
    if (options.verification_profile_id != null) {
      formData.append('verification_profile_id', String(options.verification_profile_id));
    }
    if (options.gt_comparison_profile_id != null) {
      formData.append('gt_comparison_profile_id', String(options.gt_comparison_profile_id));
    }
  }

  /**
   * Import execution from uploaded file (JSON, BibTeX, RIS, CSV, or .txt for _na no-result executions).
   * Filename must follow: name[.function]_modelversion_subscription_seedpaperID_promptID_promptversion_YYMMDD_HHMMSS[_comment].json|.bib|.ris|.csv|.txt
   * Example: chatgpt.consensus_gpt4_free_test1_prompt1_v3_250729_131049.json
   * Options (when server returns missing_data): seed_paper_id, seed_paper_content (BibTeX), seed_paper_alias,
   *   prompt_id, prompt_content so the server can create missing records and continue.
   * Options: execution_comment (for _na .txt imports – file body stored as execution comment).
   *   verification_profile_id, gt_comparison_profile_id (omit for server defaults).
   * Returns { status: 'success'|'pending', execution_id?, insertion_report?, ... } or { status: 'missing_data', ... }.
   * When status is pending/running with execution_id, open GET /api/executions/{id}/events for live activity_log.
   */
  async importExecutionFromFile(file, options = {}) {
    const formData = new FormData();
    formData.append('file', file);
    this._appendImportExecutionOptions(formData, options);
    return this.request('/api/executions/import', {
      method: 'POST',
      headers: {}, // Let browser set Content-Type for FormData (multipart/form-data)
      body: formData,
    });
  }

  /**
   * Import one or more execution export files. Single file uses multipart field `file`; two or more use repeated `files` parts (OpenAPI).
   * Batch responses include total_files, outcome_counts, and results[]; single-file responses stay a flat object.
   */
  async importExecutionFromFiles(files, options = {}) {
    const list = Array.isArray(files) ? files : [];
    if (list.length === 0) {
      throw new Error('No files selected');
    }
    const formData = new FormData();
    if (list.length === 1) {
      formData.append('file', list[0]);
    } else {
      for (const f of list) {
        formData.append('files', f);
      }
    }
    this._appendImportExecutionOptions(formData, options);
    return this.request('/api/executions/import', {
      method: 'POST',
      headers: {},
      body: formData,
    });
  }

